#include "persistence/Persistence.h"
#include <nlohmann/json.hpp>
#include <chrono>
#include <fstream>
#include <type_traits>

namespace microsw::persistence { namespace {
using Json=nlohmann::ordered_json;
Json p2(const geometry::Point2& p){return{{"x",p.x()},{"y",p.y()}};} Json p3(const geometry::Point3& p){return{{"x",p.x()},{"y",p.y()},{"z",p.z()}};} Json v3(const math::Vector3& v){return{{"x",v.x()},{"y",v.y()},{"z",v.z()}};}
geometry::Point2 rp2(const Json&j){return{j.at("x").get<double>(),j.at("y").get<double>()};} geometry::Point3 rp3(const Json&j){return{j.at("x").get<double>(),j.at("y").get<double>(),j.at("z").get<double>()};} math::Vector3 rv3(const Json&j){return{j.at("x").get<double>(),j.at("y").get<double>(),j.at("z").get<double>()};}
const char* sub(sketch::SubElementKind k){switch(k){case sketch::SubElementKind::LineStart:return"line_start";case sketch::SubElementKind::LineEnd:return"line_end";case sketch::SubElementKind::LineBody:return"line_body";case sketch::SubElementKind::CircleCenter:return"circle_center";case sketch::SubElementKind::CircleRadius:return"circle_radius";}throw std::invalid_argument{"Unknown sub-element"};}
sketch::SubElementKind rsub(const std::string&t){if(t=="line_start")return sketch::SubElementKind::LineStart;if(t=="line_end")return sketch::SubElementKind::LineEnd;if(t=="line_body")return sketch::SubElementKind::LineBody;if(t=="circle_center")return sketch::SubElementKind::CircleCenter;if(t=="circle_radius")return sketch::SubElementKind::CircleRadius;throw std::invalid_argument{"Unknown sub-element token"};}
Json ref(sketch::SketchElementRef r){return{{"entityId",r.entity.value()},{"kind",sub(r.kind)}};} sketch::SketchElementRef rref(const Json&j){return{sketch::SketchEntityId{j.at("entityId").get<std::uint32_t>()},rsub(j.at("kind").get<std::string>())};}
Json entity(const sketch::SketchEntity&e){Json j{{"id",e.id().value()}};std::visit([&](const auto&x){using T=std::decay_t<decltype(x)>;if constexpr(std::is_same_v<T,sketch::SketchLine>){j["type"]="line";j["a"]=p2(x.geometry.a());j["b"]=p2(x.geometry.b());}else if constexpr(std::is_same_v<T,sketch::SketchCircle>){j["type"]="circle";j["center"]=p2(x.geometry.center());j["radius"]=x.geometry.radius();}else{j["type"]="arc";j["center"]=p2(x.geometry.center());j["radius"]=x.geometry.radius();j["startAngle"]=x.geometry.startAngle();j["sweepAngle"]=x.geometry.sweepAngle();}},e.geometry());return j;}
sketch::SketchEntity rentity(const Json&j){sketch::SketchEntityId id{j.at("id").get<std::uint32_t>()};auto t=j.at("type").get<std::string>();if(t=="line")return{id,sketch::SketchLine{{rp2(j.at("a")),rp2(j.at("b"))}}};if(t=="circle")return{id,sketch::SketchCircle{{rp2(j.at("center")),j.at("radius").get<double>()}}};if(t=="arc")return{id,sketch::SketchArc{{rp2(j.at("center")),j.at("radius").get<double>(),j.at("startAngle").get<double>(),j.at("sweepAngle").get<double>()}}};throw std::invalid_argument{"Unknown entity token"};}
Json constraint(const sketch::SketchConstraint&c){Json j{{"id",c.id().value()}};std::visit([&](const auto&x){using T=std::decay_t<decltype(x)>;if constexpr(std::is_same_v<T,sketch::Coincident>){j["type"]="coincident";j["first"]=ref(x.first);j["second"]=ref(x.second);}else if constexpr(std::is_same_v<T,sketch::Horizontal>){j["type"]="horizontal";j["line"]=ref(x.line);}else if constexpr(std::is_same_v<T,sketch::Vertical>){j["type"]="vertical";j["line"]=ref(x.line);}else if constexpr(std::is_same_v<T,sketch::Parallel>){j["type"]="parallel";j["first"]=ref(x.first);j["second"]=ref(x.second);}else if constexpr(std::is_same_v<T,sketch::Perpendicular>){j["type"]="perpendicular";j["first"]=ref(x.first);j["second"]=ref(x.second);}else if constexpr(std::is_same_v<T,sketch::HorizontalDistance>){j["type"]="horizontal_distance";j["first"]=ref(x.first);j["second"]=ref(x.second);j["value"]=x.value;}else if constexpr(std::is_same_v<T,sketch::VerticalDistance>){j["type"]="vertical_distance";j["first"]=ref(x.first);j["second"]=ref(x.second);j["value"]=x.value;}else if constexpr(std::is_same_v<T,sketch::LineLength>){j["type"]="line_length";j["line"]=ref(x.line);j["value"]=x.value;}else{j["type"]="circle_radius";j["radius"]=ref(x.radius);j["value"]=x.value;}},c.value());return j;}
sketch::SketchConstraint rconstraint(const Json&j){sketch::SketchConstraintId id{j.at("id").get<std::uint32_t>()};auto t=j.at("type").get<std::string>();if(t=="coincident")return{id,sketch::Coincident{rref(j.at("first")),rref(j.at("second"))}};if(t=="horizontal")return{id,sketch::Horizontal{rref(j.at("line"))}};if(t=="vertical")return{id,sketch::Vertical{rref(j.at("line"))}};if(t=="parallel")return{id,sketch::Parallel{rref(j.at("first")),rref(j.at("second"))}};if(t=="perpendicular")return{id,sketch::Perpendicular{rref(j.at("first")),rref(j.at("second"))}};if(t=="horizontal_distance")return{id,sketch::HorizontalDistance{rref(j.at("first")),rref(j.at("second")),j.at("value").get<double>()}};if(t=="vertical_distance")return{id,sketch::VerticalDistance{rref(j.at("first")),rref(j.at("second")),j.at("value").get<double>()}};if(t=="line_length")return{id,sketch::LineLength{rref(j.at("line")),j.at("value").get<double>()}};if(t=="circle_radius")return{id,sketch::CircleRadius{rref(j.at("radius")),j.at("value").get<double>()}};throw std::invalid_argument{"Unknown constraint token"};}
Json sketchJson(const sketch::Sketch&s){Json es=Json::array(),cs=Json::array();for(auto id:s.entityIds())es.push_back(entity(s.find(id)));for(auto id:s.constraintIds())cs.push_back(constraint(s.findConstraint(id)));auto&p=s.plane();return{{"plane",{{"origin",p3(p.origin())},{"xAxis",v3(p.xAxis())},{"yAxis",v3(p.yAxis())}}},{"nextEntityId",s.nextEntityId()},{"nextConstraintId",s.nextConstraintId()},{"entities",es},{"constraints",cs}};}
sketch::Sketch rsketch(const Json&j){auto&es=j.at("entities");auto&cs=j.at("constraints");if(!es.is_array()||!cs.is_array()||es.size()>maximumSketchEntityCount||cs.size()>maximumSketchConstraintCount)throw std::invalid_argument{"Sketch limit exceeded"};auto&pj=j.at("plane");sketch::SketchPlane plane{rp3(pj.at("origin")),rv3(pj.at("xAxis")),rv3(pj.at("yAxis"))};std::vector<sketch::SketchEntity> ev;std::vector<sketch::SketchConstraint>cv;for(auto&e:es)ev.push_back(rentity(e));for(auto&c:cs)cv.push_back(rconstraint(c));return sketch::Sketch::restore(plane,std::move(ev),j.at("nextEntityId").get<std::uint32_t>(),std::move(cv),j.at("nextConstraintId").get<std::uint32_t>());}
const char* bop(modeling::BooleanOperation o){switch(o){case modeling::BooleanOperation::Union:return"union";case modeling::BooleanOperation::Difference:return"difference";case modeling::BooleanOperation::Intersection:return"intersection";}throw std::invalid_argument{"Unknown boolean"};} modeling::BooleanOperation rbop(const std::string&t){if(t=="union")return modeling::BooleanOperation::Union;if(t=="difference")return modeling::BooleanOperation::Difference;if(t=="intersection")return modeling::BooleanOperation::Intersection;throw std::invalid_argument{"Unknown boolean token"};}
const char* cutdir(features::CutDirection d){return d==features::CutDirection::Forward?"forward":"reverse";} features::CutDirection rcutdir(const std::string&t){if(t=="forward")return features::CutDirection::Forward;if(t=="reverse")return features::CutDirection::Reverse;throw std::invalid_argument{"Unknown cut direction"};}
const char* cap(features::ExtrudeCapRole role){return role==features::ExtrudeCapRole::StartCap?"startCap":"endCap";}
features::ExtrudeCapRole rcap(const std::string&t){if(t=="startCap")return features::ExtrudeCapRole::StartCap;if(t=="endCap")return features::ExtrudeCapRole::EndCap;throw std::invalid_argument{"Unknown cap role"};}
Json supportJson(const features::SketchFeature& value){if(const auto*semantic=std::get_if<features::SemanticFaceSupport>(&value.support))return{{"kind","semanticFace"},{"sourceFeatureId",semantic->sourceFeatureId.value()},{"capRole",cap(semantic->capRole)}};auto&p=value.sketch.plane();return{{"kind","explicitPlane"},{"plane",{{"origin",p3(p.origin())},{"xAxis",v3(p.xAxis())},{"yAxis",v3(p.yAxis())}}}};}
features::SketchSupport rsupport(const Json&j){auto kind=j.at("kind").get<std::string>();if(kind=="explicitPlane")return features::ExplicitPlaneSupport{};if(kind=="semanticFace")return features::SemanticFaceSupport{features::FeatureId{j.at("sourceFeatureId").get<std::uint32_t>()},rcap(j.at("capRole").get<std::string>())};throw std::invalid_argument{"Unknown Sketch support kind"};}
Json modelJson(const features::FeatureModel&m){Json a=Json::array();for(auto&r:m.history()){Json f{{"id",r.id().value()},{"displayName",r.displayName()}};if(r.kind()==features::FeatureKind::Sketch){auto&d=std::get<features::SketchFeature>(r.data());f["kind"]="sketch";f["sketch"]=sketchJson(d.sketch);f["support"]=supportJson(d);}else if(r.kind()==features::FeatureKind::Extrude){auto&d=std::get<features::ExtrudeFeature>(r.data());f["kind"]="extrude";f["sourceSketchFeatureId"]=d.sourceSketchFeatureId.value();f["distance"]=d.distance;}else if(r.kind()==features::FeatureKind::Boolean){auto&d=std::get<features::BooleanFeature>(r.data());f["kind"]="boolean";f["inputA"]=d.inputA.value();f["inputB"]=d.inputB.value();f["operation"]=bop(d.operation);}else if(r.kind()==features::FeatureKind::CutExtrude){auto&d=std::get<features::CutExtrudeFeature>(r.data());f["kind"]="cutExtrude";f["sourceSketchFeatureId"]=d.sourceSketchFeatureId.value();f["targetResultFeatureId"]=d.targetResultFeatureId.value();f["distance"]=d.distance;f["direction"]=cutdir(d.direction);}else throw std::invalid_argument{"Unsupported feature kind"};a.push_back(f);}Json fm{{"nextFeatureId",m.nextFeatureId()},{"features",a}};fm["resultFeatureId"]=m.resultFeatureId().isValid()?Json(m.resultFeatureId().value()):Json(nullptr);return{{"formatVersion",2},{"featureModel",fm}};}
features::FeatureModel rmodel(const Json&r){if(!r.is_object()||!r.contains("formatVersion"))throw std::invalid_argument{"Missing version"};const auto version=r.at("formatVersion").get<int>();if(version!=1&&version!=2)throw std::domain_error{"Unsupported version"};auto&fm=r.at("featureModel");auto&a=fm.at("features");if(!a.is_array()||a.size()>maximumFeatureCount)throw std::invalid_argument{"Feature limit exceeded"};std::vector<features::PersistedFeature>v;for(auto&f:a){auto id=features::FeatureId{f.at("id").get<std::uint32_t>()};auto t=f.at("kind").get<std::string>();features::FeatureKind k;features::FeatureData d;if(t=="sketch"){k=features::FeatureKind::Sketch;auto sketch=rsketch(f.at("sketch"));auto support=version==1?features::SketchSupport{features::ExplicitPlaneSupport{}}:rsupport(f.at("support"));d=features::SketchFeature{std::move(sketch),std::move(support)};}else if(t=="extrude"){k=features::FeatureKind::Extrude;d=features::ExtrudeFeature{features::FeatureId{f.at("sourceSketchFeatureId").get<std::uint32_t>()},f.at("distance").get<double>()};}else if(t=="boolean"){k=features::FeatureKind::Boolean;d=features::BooleanFeature{features::FeatureId{f.at("inputA").get<std::uint32_t>()},features::FeatureId{f.at("inputB").get<std::uint32_t>()},rbop(f.at("operation").get<std::string>())};}else if(t=="cutExtrude"&&version==2){k=features::FeatureKind::CutExtrude;d=features::CutExtrudeFeature{features::FeatureId{f.at("sourceSketchFeatureId").get<std::uint32_t>()},features::FeatureId{f.at("targetResultFeatureId").get<std::uint32_t>()},f.at("distance").get<double>(),rcutdir(f.at("direction").get<std::string>())};}else throw std::invalid_argument{"Unknown feature token"};v.push_back({id,k,f.at("displayName").get<std::string>(),std::move(d)});}features::FeatureId result;if(!fm.at("resultFeatureId").is_null())result=features::FeatureId{fm.at("resultFeatureId").get<std::uint32_t>()};return features::FeatureModel::restore(std::move(v),result,fm.at("nextFeatureId").get<std::uint32_t>());}

}
SaveResult saveFeatureModel(const features::FeatureModel&m,const std::filesystem::path&p)noexcept{try{if(p.empty()||p.filename().empty())return{SaveStatus::InvalidPath,"Destination required"};auto text=modelJson(m).dump(2);auto temp=p;temp += ".tmp-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count());{std::ofstream s(temp,std::ios::binary|std::ios::trunc);if(!s)return{SaveStatus::IoError,"Cannot create temporary file"};s<<text;s.flush();if(!s){s.close();std::error_code e;std::filesystem::remove(temp,e);return{SaveStatus::IoError,"Cannot write temporary file"};}}std::error_code e;if(std::filesystem::exists(p,e)){auto backup=p;backup += ".replace-backup";std::filesystem::remove(backup,e);e.clear();std::filesystem::rename(p,backup,e);if(e){std::filesystem::remove(temp,e);return{SaveStatus::IoError,"Cannot replace destination"};}std::filesystem::rename(temp,p,e);if(e){std::error_code x;std::filesystem::rename(backup,p,x);std::filesystem::remove(temp,x);return{SaveStatus::IoError,"Cannot install file"};}std::filesystem::remove(backup,e);}else{std::filesystem::rename(temp,p,e);if(e){std::filesystem::remove(temp,e);return{SaveStatus::IoError,"Cannot install file"};}}return{};}catch(const nlohmann::json::exception&e){return{SaveStatus::SerializationError,e.what()};}catch(const std::exception&e){return{SaveStatus::IoError,e.what()};}}
OpenResult openFeatureModel(const std::filesystem::path&p)noexcept{try{std::error_code e;auto size=std::filesystem::file_size(p,e);if(e||size>maximumFileSize)return{OpenStatus::IoError,e?"Cannot read file":"File too large",{}};std::ifstream s(p,std::ios::binary);if(!s)return{OpenStatus::IoError,"Cannot open file",{}};Json j;try{s>>j;}catch(const nlohmann::json::parse_error&x){return{OpenStatus::ParseError,x.what(),{}};}auto m=rmodel(j);auto rr=m.rebuild();return{rr.status==features::RebuildStatus::Failed?OpenStatus::SuccessRebuildFailed:OpenStatus::SuccessRebuilt,rr.diagnostic,std::move(m)};}catch(const std::domain_error&e){return{OpenStatus::UnsupportedVersion,e.what(),{}};}catch(const std::exception&e){return{OpenStatus::InvalidModel,e.what(),{}};}}
}
